logger.message:
#[%dw 2.0
output application/json skipNullOn="everywhere"
import modules::errorHandler::ErrorUtils
import modules::errorHandler::ObjectUtils
---
{
 	attributes: attributes,
 	handledError: if (ObjectUtils::isObject(payload) and payload.code?) 
 		payload 
 		else null,
 	causedBy: 
 		if (!isEmpty(error))
 			ErrorUtils::cleanup(error)
		else null,
	context: {
		operationContext: vars.operationContext,
		remoteCall: vars.remoteCall
	}	
}]

ee:message.ee:set-payload:
%dw 2.0
output application/java
import modules::errorHandler::ErrorUtils
import modules::errorHandler::ContextUtils

var errorCause = 
	if (vars.isBusinessError default false) 
		null 
	else 
		(payload.causedBy default ErrorUtils::cleanup(error))

var isBusinessError = vars.isBusinessError default false		

fun checkIfTransient(error) = do {
  var transientErrors = vars.requestConfig.transientErrors default []
  ---
  //TODO olamiral: use LLM / RAG to determine if error is transient or not
  transientErrors contains (error.errorType default "APP:UNKNOW")
}


// TODO olamiral: add logic to build causedBy when exists error.errorMessage.attributes.statusCode 
//   - payload is a handled error
//   - payload is not a handled error

---
{
	code: payload.code default "500",
	message: payload.message,
	isBusinessError: isBusinessError,
	isTransient: 
		if (isBusinessError) null
		else
			(payload.isTransient default checkIfTransient(errorCause)),
	details: payload.details,	
	correlationId: payload.correlationId default correlationId,
	timestamp: now() >> "UTC",
	causedBy: errorCause,
	context: if (isBusinessError) null
		else ContextUtils::getContextFrom(vars.operationContext.name, vars.remoteCall) 

}
